<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/app.php';
require_once __DIR__ . '/includes/blog/blog-functions.php';
$pdo=mg_db();$schema=mg_blog_schema_ready($pdo);$slug=mg_blog_slugify((string)($_GET['slug']??''),'');$category=$schema['ready']&&$slug!==''?mg_blog_category_by_slug($pdo,$slug):null;if(!$category){http_response_code(404);} $page=max(1,(int)($_GET['page']??1));$limit=9;$offset=($page-1)*$limit;$posts=$category?mg_blog_list_public_posts($pdo,['category_slug'=>(string)$category['slug'],'limit'=>$limit,'offset'=>$offset]):[];$totalPosts=$category?mg_blog_count_public_posts($pdo,['category_slug'=>(string)$category['slug']]):0;$totalPages=max(1,(int)ceil($totalPosts/$limit));$categories=$schema['ready']?mg_blog_categories($pdo,true):[];function mg_blog_category_page_url(string $slug,int $page): string{$q=['slug'=>$slug];if($page>1){$q['page']=$page;}return '/blog-category.php?'.http_build_query($q);} $page_title=$category?(string)$category['name'].' | Microgifter Blog':'Blog Category Not Found | Microgifter';$page_section='blog';$header_mode='public';$page_body_class='mg-blog-page';$page_styles=['/assets/css/blog.css','/assets/css/blog-launch.css'];$page_meta=['description'=>$category?((string)($category['description']?:'Microgifter articles in '.$category['name'].'.')):'Microgifter blog category not found.','canonical'=>'https://microgifter.com/blog-category.php?slug='.rawurlencode($slug),'og_title'=>$category?(string)$category['name'].' | Microgifter Blog':'Microgifter Blog','og_description'=>$category?((string)($category['description']?:'Microgifter category articles.')):'Microgifter blog category not found.','robots'=>$category?'':'noindex'];$page_manifest=['id'=>'blog-category','title'=>$page_title,'section'=>$page_section,'header_mode'=>$header_mode,'assets'=>['universal-header'],'header_controls'=>[],'description'=>$page_meta['description'],'public_header'=>['presentation'=>false,'links'=>[['label'=>'Blog','href'=>'/blog.php'],['label'=>'Investors','href'=>'/investors.php'],['label'=>'Book A Demo','href'=>'/learn-more.php']]],'onboarding'=>['enabled'=>false,'page'=>'blog-category','sections'=>[]]];require __DIR__.'/includes/header.php';
?>
<main class="mg-blog-main"><?php if(!$category): ?><section class="mg-blog-wrap mg-blog-empty-panel"><span class="mg-blog-eyebrow">Category not found</span><h1>This blog category is not available.</h1><p>The category may be inactive or the URL may have changed.</p><a class="mg-blog-primary-link" href="/blog.php">Back to blog</a></section><?php else: ?><section class="mg-blog-hero is-category"><div class="mg-blog-wrap mg-blog-hero-grid"><div class="mg-blog-hero-copy"><a class="mg-blog-back" href="/blog.php">← All articles</a><span class="mg-blog-eyebrow">Blog category</span><h1><?= mg_e((string)$category['name']) ?></h1><p><?= mg_e((string)($category['description']?:'Articles, product thinking, and merchant education from Microgifter.')) ?></p></div><div class="mg-blog-hero-card"><span>Category focus</span><strong><?= mg_e((string)$category['name']) ?></strong><p>Use category pages to build SEO surfaces around Microgifter’s strongest commercial themes.</p></div></div></section><section class="mg-blog-wrap mg-blog-layout"><div><div class="mg-blog-section-head"><div><span class="mg-blog-eyebrow">Latest in category</span><h2><?= (int)$totalPosts ?> article<?= $totalPosts===1?'':'s' ?></h2></div></div><?php if(!$posts): ?><div class="mg-blog-empty-panel"><h3>No published articles yet.</h3><p>Check back soon for new posts in this category.</p></div><?php else: ?><div class="mg-blog-grid"><?php foreach($posts as $post): ?><article class="mg-blog-card"><a class="mg-blog-card-media" href="<?= mg_e(mg_blog_public_post_url($post)) ?>" style="<?= !empty($post['featured_image'])?'background-image:url('.mg_e((string)$post['featured_image']).')':'' ?>"></a><div class="mg-blog-card-body"><div class="mg-blog-card-top"><span><?= mg_e(mg_blog_format_date($post['published_at']??null)) ?></span><span><?= mg_blog_reading_time((string)$post['body']) ?> min read</span></div><h3><a href="<?= mg_e(mg_blog_public_post_url($post)) ?>"><?= mg_e((string)$post['title']) ?></a></h3><p><?= mg_e((string)$post['excerpt']) ?></p><div class="mg-blog-meta"><span><?= mg_e(mg_blog_author_name($post)) ?></span></div></div></article><?php endforeach; ?></div><?php if($totalPages>1): ?><nav class="mg-blog-pagination"><?php if($page>1): ?><a href="<?= mg_e(mg_blog_category_page_url((string)$category['slug'],$page-1)) ?>">← Newer</a><?php endif; ?><span>Page <?= (int)$page ?> of <?= (int)$totalPages ?></span><?php if($page<$totalPages): ?><a href="<?= mg_e(mg_blog_category_page_url((string)$category['slug'],$page+1)) ?>">Older →</a><?php endif; ?></nav><?php endif; ?><?php endif; ?></div><aside class="mg-blog-sidebar"><section><h2>All categories</h2><div class="mg-blog-category-list"><?php foreach($categories as $item): ?><a class="<?= (string)$item['slug']===(string)$category['slug']?'is-active':'' ?>" href="<?= mg_e(mg_blog_public_category_url($item)) ?>"><?= mg_e((string)$item['name']) ?></a><?php endforeach; ?></div></section></aside></section><?php endif; ?></main>
